    "---rel": "icon",
    "--class": "s-prose",
    "@index": 0,
    "@tail": ",\nthe company began releasing periodic \"data dumps\" containing most types of\nuser-contributed content on the site. These were available for download through\nBitTorrent, so that the community would always be able to continue seeding the\ncontent so it remains available, even if the company themselves ceased to do so.\nFrom January 2014 to April 2024, the latest release was also available for\ndownload from the Internet Archive.",
    "@text": "Starting in June 2009",
    "href": "https://web.archive.org/web/20090611145537/https://blog.stackoverflow.com/2009/06/stack-overflow-creative-commons-data-dump"
  },
  {
    "": "p",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 13,
    "@tail": "\n",
    "@text": "From its inception in September 2008, user content on Stack Overflow (and later\nthe broader Stack Exchange Network) has been released under a Creative Commons\nLicense.\n"
  },
