    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 14,
    "@tail": "\n",
    "@text": "This was intended to help set Stack Overflow apart from some of the Q&A sites\nthat had existed in the past, which kept user contributions under restrictive\nlicenses and tight control, and tended to become more user-hostile over time.\nThis spirit was described by Co-Founder and CEO Joel Spolsky,\n"
  },
  {
    "": "p",
    "-": "blockquote",
    "--": "main",
    "---": "link",
    "----": null,
    "---href": "data:;base64,=",
    "---rel": "icon",
    "--class": "s-prose",
    "@index": 0,
    "@tail": "\n",
    "@text": "From day one, we used the CC-wiki license. It's basically a license that says\nthat we don't own the content that's on there, which is why we make those\ndatabase dumps that are available."
  },
  {
    "": "p",
    "-": "blockquote",
    "--": "main",
    "---": "link",
    "----": null,
    "---href": "data:;base64,=",
    "---rel": "icon",
    "--class": "s-prose",
    "@index": 1,
    "@tail": "\n",
    "@text": "We wanted to make sure that if no matter what happens, literally no matter who\nwe sell to, or raise money from, or turn the site over to, and even if they\ntake Stack Overflow, and make it an evil site where you have to pay to look at\nthings and there's pop-up ads and pop-under ads, and you know, dancing\nchariots of fire that cross the screen and punch the monkey, and [...] it just\nbecomes a big gigantic spam site."
  },
  {
    "": "p",
    "-": "blockquote",
    "--": "main",
    "---": "link",
    "----": null,
    "---href": "data:;base64,=",
    "---rel": "icon",
    "--class": "s-prose",
    "@index": 2,
    "@tail": "\n",
    "@text": "Doesn't matter because you can just take the latest CC-wiki download that we\nprovided and go start your own site saying \"you know what, this is gonna be\nthe clean version\". And I think a lot of people will follow you. We very, very\ndeliberately built Stack Overflow in a way that there wouldn't be any chance\nof locking it down."
  },
  {
    "": "blockquote",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 15,
    "@tail": "\n",
    "@text": "\n"
  },
  {
    "": "a",
    "-": "p",
    "--": "main",
    "---": "link",
    "----": null,
    "---href": "data:;base64,=",
    "---rel": "icon",
    "--class": "s-prose",
    "@index": 0,
    "@tail": "\nthe company announced that going forward, the data dumps would not be released\nas torrents or uploaded to the Internet Archive. Instead, users would need to\nlog in to download them directly from the Stack Exchange website, so that they\ncould monitor who was downloading them, with the explicit threat that they would\nblock users from downloading if they were using the data for a purpose that the\ncompany didn't approve of. Additionally, there would no longer be a single\nrelease containing data from the entire network. Instead, users would need to\nmanually go to each of the 368 sites in the network to download its data.",
    "@text": "in July 2024",
    "href": "https://meta.stackexchange.com/questions/401324/announcing-a-change-to-the-data-dump-process"
  },
  {
    "": "p",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 16,
    "@tail": "\n",
    "@text": "Unfortunately,\n"
  },
  {
    "": "p",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 17,
    "@tail": "\n",
    "@text": "In order to preserve open access to Stack Exchange community data, some\ncommunity members will be going through the effort to download the dumps from\nall sites across the network, and re-distributing the complete collection as\ntorrents resembling those that were previously provided by the company. Some of\nthese will be in original XML format, while others will be converted to other\nformats that are more convenient to use directly."
  },
  {
    "": "p",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 18,
    "@tail": "\n",
    "@text": "This site exists to provide an index of all releases, including\ncommunity-aggregated ones going forward as well as the company-provided ones\nfrom the past."
  },
  {
    "": "a",
    "-": "h2",
    "--": "main",
    "---": "link",
    "----": null,
    "---href": "data:;base64,=",
