    "@text": "stackoverflow.com/help/licensing",
    "href": "https://stackoverflow.com/help/licensing"
  },
  {
    "": "p",
    "-": "main",
    "--": "link",
    "---": null,
    "--href": "data:;base64,=",
    "--rel": "icon",
    "-class": "s-prose",
    "@index": 20,
    "@tail": "\n",
    "@text": "Each item in these releases is copyright its respective authors and editors, who\nare identified in the release's data. Each item is distributed under a Creative\nCommons Attribution-ShareAlike license (CC BY-SA, previously also known as\nCC-Wiki), but the exact version of the license depends on the date that on which\nthe item was contributed. According to\n"
  },
